WITH valid_departments AS (SELECT * FROM departments WHERE location IS NULL AND dept_name != 'Sales'), budget_bucket_summary AS (SELECT CASE WHEN budget >= 3178000 THEN 'high' WHEN budget >= 1737000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(budget) AS budget_count FROM valid_departments GROUP BY CASE WHEN budget >= 3178000 THEN 'high' WHEN budget >= 1737000 THEN 'mid' ELSE 'low' END) SELECT * FROM budget_bucket_summary
